const state={token:localStorage.getItem('ledgerly_token'),user:null,page:'dashboard',data:{},selectedPlan:'trial'};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.style.background=error?'#c33f56':'#101828';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
async function api(url,options={}){const token=state.token||localStorage.getItem('ledgerly_token');const headers={'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(options.headers||{})};const r=await fetch(url,{...options,headers});let d={};try{d=await r.json()}catch{}if(r.status===401){localStorage.removeItem('ledgerly_token');state.token=null;throw new Error(d.message||'Please sign in')}if(!r.ok)throw new Error(d.message||'Something went wrong');return d}
function openModal(html){$('#modalContent').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
function setAuth(mode){$$('.auth-tab').forEach(b=>b.classList.toggle('active',b.dataset.auth===mode));$('#loginForm').classList.toggle('hidden',mode!=='login');$('#registerForm').classList.toggle('hidden',mode!=='register')}
function showAuthForms(mode='register'){ $('#signupPlanChooser').classList.add('hidden');$('#authFormsArea').classList.remove('hidden');setAuth(mode);$('#selectedPlanSummary').classList.toggle('hidden',mode!=='register');$('#changePlanBtn').classList.toggle('hidden',mode!=='register');if(mode==='register'){const selected=state.selectedPlan==='trial'?{name:'30-day free trial',price:0}:state.signupPlans?.find(p=>p._id===state.selectedPlan);$('#selectedPlanSummary').textContent=selected?(state.selectedPlan==='trial'?'Selected: 30-day free trial — no payment method required.':`Selected: ${selected.name} — ${money(selected.price)} / month. You'll complete secure payment checkout after creating your account.`):'Choose your plan.'}}
async function loadSignupPlans(){const holder=$('#signupPlanCards');if(!holder)return;try{const plans=await fetch('/api/plans').then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.message||'Could not load plans');return d});state.signupPlans=plans;holder.innerHTML=`<button class="signup-plan-option" type="button" data-signup-plan="trial"><span class="signup-plan-top"><b>30-day free trial</b><strong>₹0</strong></span><small>Full access for 30 days · No payment method required</small><span class="trial-label">BEST WAY TO TRY SAVRO</span></button>`+plans.map(p=>`<button class="signup-plan-option" type="button" data-signup-plan="${esc(p._id)}"><span class="signup-plan-top"><b>${esc(p.name)}</b><strong>${money(p.price)}<span style="font:500 9px sans-serif;color:#9aa5b8"> / month</span></strong></span><small>${(Array.isArray(p.features)?p.features:[]).map(esc).join(' · ')}</small></button>`).join('');holder.querySelectorAll('[data-signup-plan]').forEach(b=>b.onclick=()=>{state.selectedPlan=b.dataset.signupPlan;showAuthForms('register')})}catch(e){holder.innerHTML=`<div class="empty">${esc(e.message)}. Please refresh to try again.</div>`}}
$('#existingAccountBtn').onclick=()=>showAuthForms('login');$('#changePlanBtn').onclick=()=>{$('#authFormsArea').classList.add('hidden');$('#signupPlanChooser').classList.remove('hidden')};$$('.auth-tab').forEach(b=>b.onclick=()=>setAuth(b.dataset.auth));$$('[data-close-modal]').forEach(b=>b.onclick=closeModal);
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value})});state.token=d.token;localStorage.setItem('ledgerly_token',d.token);state.user=d.user;showApp()}catch(err){toast(err.message||'Could not sign in',true)}};
$('#registerForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify({name:$('#regName').value.trim(),businessName:$('#regBusiness').value.trim(),email:$('#regEmail').value.trim(),password:$('#regPassword').value,selectedPlan:state.selectedPlan})});state.token=d.token;localStorage.setItem('ledgerly_token',d.token);state.user=d.user;showApp();toast('Workspace created 🎉')}catch(err){toast(err.message||'Could not create account',true)}};
let forgotResetToken='';
function showForgotStage(stage){$('#loginForm').classList.add('hidden');$('#registerForm').classList.add('hidden');$('#forgotPasswordPanel').classList.remove('hidden');$('#forgotEmailForm').classList.toggle('hidden',stage!=='email');$('#forgotOtpForm').classList.toggle('hidden',stage!=='otp');$('#forgotNewPasswordForm').classList.toggle('hidden',stage!=='password');$('#forgotStatus').textContent='';$('#authFormsArea .auth-tabs').classList.add('hidden');$('#selectedPlanSummary').classList.add('hidden');$('#changePlanBtn').classList.add('hidden');if(stage==='email'){$('#forgotHeading').textContent='Reset your password';$('#forgotDescription').textContent="Enter your Savro email address and we'll send a six-digit verification code.";$('#forgotEmail').value=$('#loginEmail').value.trim();}else if(stage==='otp'){$('#forgotHeading').textContent='Check your email';$('#forgotDescription').textContent='Enter the six-digit code sent to your email. The code expires in 10 minutes.';$('#forgotOtp').focus()}else{$('#forgotHeading').textContent='Create a new password';$('#forgotDescription').textContent='Choose a strong password you have not used for this account.';$('#forgotNewPassword').focus()}}
function exitForgot(){forgotResetToken='';$('#forgotPasswordPanel').classList.add('hidden');$('#authFormsArea .auth-tabs').classList.remove('hidden');$('#loginForm').classList.remove('hidden');$('#registerForm').classList.add('hidden');$('#selectedPlanSummary').classList.remove('hidden');$('#changePlanBtn').classList.add('hidden');setAuth('login')}
$('#forgotPasswordLink').onclick=()=>showForgotStage('email');$('#forgotBackToLogin').onclick=exitForgot;
$('#forgotEmailForm').onsubmit=async e=>{e.preventDefault();const email=$('#forgotEmail').value.trim().toLowerCase();try{const d=await api('/api/auth/forgot-password/request',{method:'POST',body:JSON.stringify({email})});$('#forgotStatus').textContent=d.message||'If an account exists for that email, a code has been sent.';showForgotStage('otp');$('#forgotStatus').textContent=d.message||'If an account exists for that email, a code has been sent.';}catch(err){$('#forgotStatus').textContent=err.message||'Could not send the code.';}};
$('#resendForgotOtp').onclick=()=>$('#forgotEmailForm').requestSubmit();
$('#forgotOtpForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/forgot-password/verify',{method:'POST',body:JSON.stringify({email:$('#forgotEmail').value.trim().toLowerCase(),otp:$('#forgotOtp').value.trim()})});forgotResetToken=d.resetToken;showForgotStage('password');$('#forgotStatus').textContent='Code verified. Choose your new password.';}catch(err){$('#forgotStatus').textContent=err.message||'Could not verify the code.';}};
$('#forgotNewPasswordForm').onsubmit=async e=>{e.preventDefault();const newPassword=$('#forgotNewPassword').value,confirm=$('#forgotConfirmPassword').value;if(newPassword!==confirm){$('#forgotStatus').textContent='The passwords do not match.';return}try{const d=await api('/api/auth/forgot-password/reset',{method:'POST',body:JSON.stringify({email:$('#forgotEmail').value.trim().toLowerCase(),resetToken:forgotResetToken,newPassword})});forgotResetToken='';$('#loginEmail').value=$('#forgotEmail').value.trim().toLowerCase();$('#loginPassword').value='';exitForgot();toast(d.message||'Password reset successfully. Sign in with your new password.');}catch(err){$('#forgotStatus').textContent=err.message||'Could not reset the password.';}};
async function logout(){
  openModal(`
    <div class="signout-confirm">
      <div class="signout-icon" aria-hidden="true"><span>↪</span></div>
      <div class="signout-eyebrow">ACCOUNT SECURITY</div>
      <h3>Sign out of Savro?</h3>
      <p>You’ll be signed out of your account on this device. You can sign back in anytime.</p>
      <div class="signout-actions">
        <button type="button" class="signout-cancel" id="cancelSignOut">Stay signed in</button>
        <button type="button" class="signout-confirm-btn" id="confirmSignOut"><span>Sign out</span><span aria-hidden="true">→</span></button>
      </div>
    </div>`);
  const cancelButton = $('#cancelSignOut');
  const confirmButton = $('#confirmSignOut');
  if (cancelButton) cancelButton.onclick = closeModal;
  if (confirmButton) confirmButton.onclick = () => {
    closeModal();
    state.token = null;
    state.user = null;
    localStorage.removeItem('ledgerly_token');
    $('#appView').classList.add('hidden');
    $('#authView').classList.remove('hidden');
    toast('You have signed out');
  };
}
$('#logoutBtn').onclick=logout;$('#mobileMenu').onclick=()=>$('.sidebar').classList.toggle('open');

const refreshBtn = $('#refreshBtn');

if (refreshBtn) {
  refreshBtn.onclick = async () => {
    if (refreshBtn.disabled) return;

    refreshBtn.disabled = true;
    refreshBtn.style.opacity = '0.6';

    try {
      await render();

      const errorPanel = $('#page .panel.empty');

      if (errorPanel) {
        toast(errorPanel.textContent || 'Could not refresh data', true);
      } else {
        toast('Data refreshed successfully');
      }
    } catch (err) {
      toast(err.message || 'Could not refresh data', true);
    } finally {
      refreshBtn.disabled = false;
      refreshBtn.style.opacity = '';
    }
  };
}

$$('.nav-item').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;$$('.nav-item').forEach(x=>x.classList.toggle('active',x===b));$('.sidebar').classList.remove('open');render()});
function setAvatarLogo(logoUrl){const avatar=$('#avatar');if(!avatar)return;if(logoUrl&&/^data:image\/(png|jpeg|webp|gif);base64,/i.test(logoUrl)){avatar.innerHTML=`<img src="${logoUrl}" alt="Business logo">`;avatar.classList.add('has-logo')}else{avatar.textContent=(state.user?.name||'A')[0].toUpperCase();avatar.classList.remove('has-logo')}}
async function loadAvatarLogo(){try{const d=await api('/api/settings');setAvatarLogo(d.settings?.businessProfile?.logoUrl||'')}catch{setAvatarLogo('')}}
function showApp(){ $('#authView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#businessName').textContent=state.user.businessName||'My Business';$('#userName').textContent=state.user.name;setAvatarLogo('');loadAvatarLogo();$('#userPlan').textContent=state.user.subscriptionPlan?`${state.user.subscriptionPlan} plan`:state.user.subscriptionStatus==='trial'?'Free trial':'No plan';const trialNotice=$('#trialNotice');if(trialNotice){if(state.user.trialExpired){trialNotice.textContent='Your 30-day free trial has ended. Your existing records are safe and available in read-only mode. Choose a paid plan to resume editing.';trialNotice.classList.remove('hidden');trialNotice.classList.add('bad')}else if(state.user.subscriptionStatus==='trial'&&state.user.trialEndsAt){trialNotice.textContent=`Free trial: ${state.user.trialDaysRemaining} day(s) remaining. No payment method is required during your trial.`;trialNotice.classList.remove('hidden','bad')}else if(state.user.subscriptionStatus==='pending_payment'){trialNotice.textContent=`${state.user.subscriptionPlan||'Paid plan'} selected. Your payment is awaiting confirmation. Your workspace remains read-only until the subscription is activated.`;trialNotice.classList.remove('hidden');trialNotice.classList.add('bad')}else{trialNotice.classList.add('hidden');trialNotice.classList.remove('bad')}}$$('.admin-only').forEach(x=>x.classList.toggle('hidden',state.user.role!=='admin'));render() }
async function boot(){try{if(!state.token)throw new Error('Sign in');const d=await api('/api/auth/me');state.user=d.user;showApp()}catch{$('#appView').classList.add('hidden');$('#authView').classList.remove('hidden')}}
function layoutHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`}
async function render(){const page=$('#page');$('#pageTitle').textContent={dashboard:'Overview',sales:'Invoices',transactions:'Transactions',inventory:'Inventory',items:'Items',reports:'Reports',accounting:'Accounting',settings:'Settings',subscriptions:'Plans & Billing',admin:'Admin panel'}[state.page]||'Overview';page.innerHTML='<div class="empty">Loading your workspace…</div>';try{if(state.page==='dashboard')return await renderDashboard();if(state.page==='sales')return await renderSales();if(state.page==='transactions')return await renderTransactions();if(state.page==='inventory')return await renderInventory();if(state.page==='items')return await renderItems();if(state.page==='reports')return await renderReports();if(state.page==='accounting')return await renderAccounting();if(state.page==='settings')return await renderSettings();if(state.page==='subscriptions')return await renderSubscriptions();if(state.page==='admin')return await renderAdmin()}catch(e){page.innerHTML=`<div class="panel empty">${esc(e.message)}</div>`}}
async function renderDashboard(){const d=await api('/api/dashboard');state.data.dashboard=d;const cashflow=Array.isArray(d.cashflow)?d.cashflow:[];const maxCashflow=Math.max(1,...cashflow.flatMap(m=>[Number(m.income)||0,Number(m.expenses)||0]));$('#page').innerHTML=layoutHead('OVERVIEW','Good evening, '+esc(state.user.name.split(' ')[0])+' 👋','A clean view of the numbers that matter most.',`<button class="primary-btn" onclick="openTransaction('income')">+ Add income</button><button class="secondary-btn" onclick="openTransaction('expense')">+ Expense</button>`)+`<div class="stats"><div class="stat"><small>MONTHLY INCOME</small><b>${money(d.metrics.income)}</b><span class="up">↗ Collected this month</span></div><div class="stat"><small>MONTHLY EXPENSES</small><b>${money(d.metrics.expenses)}</b><span class="up">↘ Tracked spending</span></div><div class="stat"><small>NET PROFIT</small><b>${money(d.metrics.profit)}</b><span class="up">${d.metrics.profit>=0?'Healthy margin':'Needs attention'}</span></div><div class="stat"><small>LOW STOCK</small><b>${d.metrics.lowStock}</b><span class="up">Items need restocking</span></div></div><div class="dash-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">CASHFLOW</span><h3>Income vs expenses</h3><p>Your recent activity at a glance</p></div><span class="badge gray">Live</span></div><div class="chart-scroll" aria-label="Scrollable monthly cashflow chart"><div class="chart-inner"><div class="chart">${cashflow.map(m=>{const income=Number(m.income)||0,expenses=Number(m.expenses)||0;const incomeHeight=income?Math.max(3,income/maxCashflow*100):0;const expenseHeight=expenses?Math.max(3,expenses/maxCashflow*100):0;return `<div class="bar-col" title="${esc(m.label+' '+m.year)} — Income: ${esc(money(income))}; Expenses: ${esc(money(expenses))}"><i class="bar-income" style="height:${incomeHeight}%" title="Income: ${esc(money(income))}"></i><i class="bar-expense" style="height:${expenseHeight}%" title="Expenses: ${esc(money(expenses))}"></i></div>`}).join('')}</div><div class="chart-labels">${cashflow.map(m=>`<span title="${esc(m.label+' '+m.year)}">${esc(m.label)}</span>`).join('')}</div></div></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">HEALTH</span><h3>Business snapshot</h3><p>Where your money is going</p></div></div><div class="metric-list"><div class="metric-row"><div><i class="metric-dot green"></i><span>Income collected</span></div><b>${money(d.metrics.income)}</b></div><div class="metric-row"><div><i class="metric-dot red"></i><span>Expenses paid</span></div><b>${money(d.metrics.expenses)}</b></div><div class="metric-row"><div><i class="metric-dot green"></i><span>Net profit</span></div><b>${money(d.metrics.profit)}</b></div><div class="metric-row"><div><i class="metric-dot red"></i><span>Invoices created</span></div><b>${d.metrics.invoiceCount}</b></div></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">RECENT</span><h3>Latest transactions</h3></div><button class="action-link" onclick="go('transactions')">View all →</button></div><div class="recent-list">${d.transactions.length?d.transactions.slice(0,5).map(t=>`<div class="recent"><div><b>${esc(t.description)}</b><small>${esc(t.category||'Other')} · ${new Date(t.date).toLocaleDateString('en-IN')}</small></div><strong class="${t.type}">${t.type==='income'?'+':'-'}${money(t.amount)}</strong></div>`).join(''):'<div class="empty">No transactions yet.</div>'}</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">INVENTORY</span><h3>Low stock alerts</h3></div><button class="action-link" onclick="go('inventory')">Inventory →</button></div><div class="recent-list">${d.lowStockProducts.length?d.lowStockProducts.map(p=>`<div class="recent"><div><b>${esc(p.name)}</b><small>${esc(p.sku||'No SKU')}</small></div><span class="badge ${p.stock===0?'red':'amber'}">${p.stock} left</span></div>`).join(''):'<div class="empty">All stocked up ✨</div>'}</div></section></div>`}
function go(page){state.page=page;$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));render()}
window.go=go;
window.openTransaction=type=>{openModal(`<h3>Add ${type==='income'?'income':'expense'}</h3><p>Keep your books up to date in a few seconds.</p><form id="txForm" class="form-grid"><label>Description<input name="description" placeholder="${type==='income'?'Customer payment':'Office rent'}" required></label><label>Amount<input name="amount" type="number" min="0" step="0.01" required></label><label>Category<select name="category">${(type==='income'?['Sales','Services','Other']:['Rent','Salary','Utilities','Inventory','Marketing','Other']).map(x=>`<option>${x}</option>`).join('')}</select></label><label>Date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Party / customer<input name="partyName" placeholder="Optional"></label><label>Status<select name="paymentStatus"><option value="paid">Paid</option><option value="pending">Pending</option></select></label><label style="grid-column:1/-1">Notes<textarea name="notes" placeholder="Optional note"></textarea></label><button class="primary-btn" style="grid-column:1/-1">Save ${type}</button></form>`);$('#txForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{await api('/api/transactions',{method:'POST',body:JSON.stringify({...o,type,amount:Number(o.amount)})});closeModal();toast('Saved successfully');render()}catch(err){toast(err.message,true)}}}
async function renderTransactions(){const tx=await api('/api/transactions');$('#page').innerHTML=layoutHead('BOOKKEEPING','Transactions','Every sale and expense, organized in one place.',`<button class="primary-btn" onclick="openTransaction('income')">+ Income</button><button class="secondary-btn" onclick="openTransaction('expense')">+ Expense</button>`)+`<section class="panel table-panel"><div class="toolbar"><input id="txSearch" class="table-search" placeholder="Search transactions..."><span class="badge gray">${tx.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Party</th><th>Status</th><th>Amount</th><th></th></tr></thead><tbody id="txBody">${tx.map(t=>`<tr data-search="${esc((t.description+' '+(t.partyName||'')+' '+t.category).toLowerCase())}"><td>${new Date(t.date).toLocaleDateString('en-IN')}</td><td><b>${esc(t.description)}</b></td><td>${esc(t.category||'Other')}</td><td>${esc(t.partyName||'—')}</td><td><span class="badge ${t.paymentStatus==='paid'?'green':'amber'}">${esc(t.paymentStatus)}</span></td><td class="${t.type}">${t.type==='income'?'+':'-'}${money(t.amount)}</td><td><button class="action-link" onclick="deleteTx('${t._id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No transactions yet.</div></td></tr>'}</tbody></table></div></section>`;$('#txSearch').oninput=e=>$$('#txBody tr').forEach(r=>r.style.display=r.dataset.search.includes(e.target.value.toLowerCase())?'':'none')}
window.deleteTx=async id=>{if(!confirm('Delete this transaction?'))return;try{await api('/api/transactions/'+encodeURIComponent(id),{method:'DELETE'});toast('Transaction deleted');await renderTransactions()}catch(err){toast(err.message||'Could not delete transaction',true)}}
async function renderSales(){const invoices=await api('/api/invoices');$('#page').innerHTML=layoutHead('SALES','Invoices','Create polished invoices and keep payment status visible.',`<button class="primary-btn" onclick="openInvoice()">+ New invoice</button>`)+`<section class="panel table-panel"><div class="toolbar"><span class="badge gray">${invoices.length} invoices</span><span class="eyebrow">PRINTABLE • SHAREABLE</span></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${invoices.map(i=>`<tr><td><b>${esc(i.number)}</b></td><td>${esc(i.customer?.name||'—')}</td><td>${new Date(i.date).toLocaleDateString('en-IN')}</td><td>${money(i.total)}</td><td><span class="badge ${i.status==='paid'?'green':i.status==='cancelled'?'red':'amber'}">${esc(i.status)}</span></td><td><button class="action-link" onclick="printInvoice('${i._id}')">Print</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">Create your first invoice.</div></td></tr>'}</tbody></table></div></section>`}
window.openInvoice=()=>{openModal(`<h3>New invoice</h3><p>Create a simple customer invoice. You can print it after saving.</p><form id="invoiceForm"><div class="form-grid"><label>Customer name<input name="customerName" required></label><label>Customer phone<input name="phone"></label><label>Customer email<input name="email" type="email"></label><label>GSTIN<input name="gstin"></label></div><div class="items" id="items"><div class="item-line"><input name="itemName" placeholder="Item / service" required><input name="qty" type="number" value="1" min="1"><input name="price" type="number" placeholder="Price" min="0"><input name="tax" type="number" placeholder="Tax %" value="0" min="0"><button type="button" class="danger-btn" onclick="this.parentElement.remove()">×</button></div></div><button type="button" class="secondary-btn" onclick="addInvoiceItem()">+ Add line</button><div style="display:flex;justify-content:flex-end;margin-top:20px"><button class="primary-btn">Save invoice</button></div></form>`);$('#invoiceForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const rows=[...document.querySelectorAll('#items .item-line')].map(r=>{const x=r.querySelectorAll('input');return{name:x[0].value,qty:Number(x[1].value),price:Number(x[2].value),tax:Number(x[3].value)}});try{await api('/api/invoices',{method:'POST',body:JSON.stringify({customer:{name:f.get('customerName'),phone:f.get('phone'),email:f.get('email'),gstin:f.get('gstin')},items:rows})});closeModal();toast('Invoice created');renderSales()}catch(err){toast(err.message,true)}}}
window.addInvoiceItem=()=>{const d=document.createElement('div');d.className='item-line';d.innerHTML='<input name="itemName" placeholder="Item / service" required><input name="qty" type="number" value="1" min="1"><input name="price" type="number" placeholder="Price" min="0"><input name="tax" type="number" placeholder="Tax %" value="0" min="0"><button type="button" class="danger-btn" onclick="this.parentElement.remove()">×</button>';$('#items').appendChild(d)};
window.printInvoice=async id=>{const invoices=await api('/api/invoices');const i=invoices.find(x=>x._id===id);if(!i)return;const w=window.open('','_blank');w.document.write(`<html><head><title>${i.number}</title><style>body{font-family:Arial;padding:40px;color:#111}h1{margin:0 0 10px}table{width:100%;border-collapse:collapse;margin-top:30px}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.total{text-align:right;font-size:22px;margin-top:20px}</style></head><body><h1>${esc(state.user.businessName)}</h1><p>Invoice <b>${esc(i.number)}</b><br>${new Date(i.date).toLocaleDateString('en-IN')}</p><h3>Bill to</h3><p>${esc(i.customer.name)}<br>${esc(i.customer.phone||'')}<br>${esc(i.customer.email||'')}</p><table><tr><th>Item</th><th>Qty</th><th>Price</th><th>Tax</th><th>Total</th></tr>${i.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.qty}</td><td>${money(x.price)}</td><td>${x.tax}%</td><td>${money(x.qty*x.price*(1+x.tax/100))}</td></tr>`).join('')}</table><div class="total">Total: <b>${money(i.total)}</b></div><script>window.print()</script></body></html>`);w.document.close()}
async function renderInventory(){const products=await api('/api/products');const movements=await api('/api/stock-movements');const stockValue=products.reduce((n,p)=>n+(Number(p.buyPrice)||0)*(Number(p.stock)||0),0);const low=products.filter(p=>Number(p.stock)<=Number(p.lowStockAt??5)).length;$('#page').innerHTML=layoutHead('INVENTORY','Products & stock','Track available stock, record stock movements and monitor value.',`<button class="primary-btn" onclick="openProduct()">+ Add product</button>`)+`<div class="stats"><div class="stat"><small>TOTAL PRODUCTS</small><b>${products.length}</b><span class="up">In your catalogue</span></div><div class="stat"><small>STOCK VALUE</small><b>${money(stockValue)}</b><span class="up">Estimated at purchase price</span></div><div class="stat"><small>LOW STOCK</small><b>${low}</b><span class="up">Need restocking</span></div><div class="stat"><small>STOCK MOVEMENTS</small><b>${movements.length}</b><span class="up">Recorded changes</span></div></div><section class="panel table-panel" style="margin-top:16px"><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Buy</th><th>Sell</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>${products.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.sku||'—')}</td><td>${esc(p.category||'—')}</td><td>${money(p.buyPrice)}</td><td>${money(p.sellPrice)}</td><td><span class="badge ${Number(p.stock)<=Number(p.lowStockAt??5)?'amber':'green'}">${Number(p.stock)||0}</span></td><td>${Number(p.stock)<=Number(p.lowStockAt??5)?'<span class="badge amber">Low stock</span>':'<span class="badge green">In stock</span>'}</td><td><button class="action-link" onclick="openStockMovement('${p._id}','stock_in')">Stock in</button> <button class="action-link" onclick="openStockMovement('${p._id}','adjustment')">Adjust</button> <button class="action-link" onclick="deleteProduct('${p._id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">No products yet.</div></td></tr>'}</tbody></table></div></section><section class="panel table-panel" style="margin-top:16px"><div class="panel-head"><div><span class="eyebrow">AUDIT TRAIL</span><h3>Stock movement history</h3><p>Incoming stock and adjustments, newest first.</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Movement</th><th>Change</th><th>Previous</th><th>New stock</th><th>Reason</th></tr></thead><tbody>${movements.map(m=>`<tr><td>${new Date(m.date||m.createdAt).toLocaleString('en-IN')}</td><td><b>${esc(m.productName||'Product')}</b><small>${esc(m.sku||'')}</small></td><td>${m.type==='stock_in'?'Stock in':'Adjustment'}</td><td class="${Number(m.change)>=0?'income':'expense'}">${Number(m.change)>0?'+':''}${Number(m.change)}</td><td>${Number(m.previousStock)||0}</td><td>${Number(m.newStock)||0}</td><td>${esc(m.reason||'—')}</td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No stock movements recorded yet.</div></td></tr>'}</tbody></table></div></section>`}
window.openStockMovement=(id,type)=>{const isIn=type==='stock_in';openModal(`<h3>${isIn?'Record incoming stock':'Adjust stock'}</h3><p>${isIn?'Add received units to the current quantity.':'Increase or decrease stock after a physical count or loss.'}</p><form id="stockMovementForm" class="form-grid"><label>${isIn?'Quantity received':'Adjustment direction'}${isIn?'<input name="quantity" type="number" min="0.01" step="any" required>':'<select name="direction"><option value="1">Increase stock</option><option value="-1">Decrease stock</option></select>'}</label>${isIn?'':'<label>Quantity<input name="quantity" type="number" min="0.01" step="any" required></label>'}<label style="grid-column:1/-1">Reason<input name="reason" maxlength="500" placeholder="e.g. Supplier delivery, damaged goods, stock count" required></label><button class="primary-btn" style="grid-column:1/-1">Save stock movement</button></form>`);$('#stockMovementForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await api('/api/products/'+encodeURIComponent(id)+'/stock-movements',{method:'POST',body:JSON.stringify({type,quantity:Number(f.quantity),direction:f.direction,reason:f.reason})});closeModal();toast('Stock updated and movement recorded');await renderInventory()}catch(err){toast(err.message||'Could not update stock',true)}}}
async function renderItems(){
 const products=await api('/api/products');
 const categories=[...new Set(products.map(p=>String(p.category||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
 $('#page').innerHTML=layoutHead('ITEM CATALOGUE','Items','Manage the products you sell, their codes, categories and prices.',`<button class="primary-btn" onclick="openItem()">+ Add item</button>`)+
 `<div class="stats"><div class="stat"><small>TOTAL ITEMS</small><b>${products.length}</b><span class="up">Saved in your catalogue</span></div><div class="stat"><small>ITEM CATEGORIES</small><b>${categories.length}</b><span class="up">Organized groups</span></div><div class="stat"><small>STOCK VALUE</small><b>${money(products.reduce((n,p)=>n+(Number(p.buyPrice)||0)*(Number(p.stock)||0),0))}</b><span class="up">Estimated at buy price</span></div><div class="stat"><small>LOW STOCK</small><b>${products.filter(p=>Number(p.stock)<=Number(p.lowStockAt??5)).length}</b><span class="up">Check inventory</span></div></div>
 <section class="panel table-panel" style="margin-top:16px"><div class="toolbar"><input id="itemSearch" class="table-search" placeholder="Search item name, SKU or category..."><select id="itemCategory" aria-label="Filter by category"><option value="">All categories</option>${categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><span class="badge gray">${products.length} items</span></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Item code / SKU</th><th>Category</th><th>Purchase price</th><th>Selling price</th><th>Margin</th><th>Stock</th><th>Actions</th></tr></thead><tbody id="itemsBody">${products.map(p=>`<tr data-name="${esc((p.name+' '+(p.sku||'')+' '+(p.category||'')).toLowerCase())}" data-category="${esc(p.category||'')}"><td><b>${esc(p.name)}</b></td><td>${esc(p.sku||'—')}</td><td>${esc(p.category||'Uncategorized')}</td><td>${money(p.buyPrice)}</td><td>${money(p.sellPrice)}</td><td class="${Number(p.sellPrice)>=Number(p.buyPrice)?'income':'expense'}">${money(Number(p.sellPrice)-Number(p.buyPrice))}</td><td><span class="badge ${Number(p.stock)<=Number(p.lowStockAt??5)?'amber':'green'}">${Number(p.stock)||0}</span></td><td><button class="action-link" onclick="editItem('${p._id}')">Edit</button> <button class="action-link danger-text" onclick="deleteItem('${p._id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">No items yet. Add your first item to start your catalogue.</div></td></tr>'}</tbody></table></div></section>`;
 const filter=()=>{const q=$('#itemSearch').value.toLowerCase(),cat=$('#itemCategory').value;$$('#itemsBody tr[data-name]').forEach(r=>r.style.display=r.dataset.name.includes(q)&&(!cat||r.dataset.category===cat)?'':'none')};$('#itemSearch').oninput=filter;$('#itemCategory').onchange=filter;
}
window.openItem=()=>itemModal();
window.editItem=async id=>{try{const p=(await api('/api/products')).find(x=>x._id===id);if(!p)throw new Error('Item not found.');itemModal(p)}catch(e){toast(e.message,true)}};
function itemModal(p=null){openModal(`<h3>${p?'Edit item':'Add item'}</h3><p>Item details are shared with Inventory, so prices and stock stay consistent.</p><form id="itemForm" class="form-grid"><label>Item name<input name="name" value="${esc(p?.name||'')}" required maxlength="120"></label><label>Item code / SKU<input name="sku" value="${esc(p?.sku||'')}" maxlength="80"></label><label>Category<input name="category" value="${esc(p?.category||'')}" placeholder="e.g. Clothing, Services"></label><label>Opening / current stock<input name="stock" type="number" min="0" step="any" value="${Number(p?.stock)||0}" required></label><label>Purchase price (₹)<input name="buyPrice" type="number" min="0" step="0.01" value="${Number(p?.buyPrice)||0}" required></label><label>Selling price (₹)<input name="sellPrice" type="number" min="0" step="0.01" value="${Number(p?.sellPrice)||0}" required></label><label>Low stock alert at<input name="lowStockAt" type="number" min="0" step="any" value="${p?.lowStockAt===undefined?5:Number(p.lowStockAt)}" required></label><button class="primary-btn" style="grid-column:1/-1">${p?'Save changes':'Save item'}</button></form>`);$('#itemForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{await api(p?'/api/products/'+encodeURIComponent(p._id):'/api/products',{method:p?'PATCH':'POST',body:JSON.stringify(o)});closeModal();toast(p?'Item updated':'Item added');await renderItems()}catch(err){toast(err.message||'Could not save item',true)}}}
window.deleteItem=async id=>{if(!confirm('Delete this item from the catalogue and inventory? This cannot be undone.'))return;try{await api('/api/products/'+encodeURIComponent(id),{method:'DELETE'});toast('Item deleted');await renderItems()}catch(e){toast(e.message||'Could not delete item',true)}};
window.openProduct=()=>{openModal(`<h3>Add product</h3><p>Track stock and pricing for products you sell.</p><form id="productForm" class="form-grid"><label>Product name<input name="name" required></label><label>SKU<input name="sku"></label><label>Category<input name="category"></label><label>Opening stock<input name="stock" type="number" min="0" value="0"></label><label>Buy price<input name="buyPrice" type="number" min="0" value="0"></label><label>Sell price<input name="sellPrice" type="number" min="0" value="0"></label><label>Low stock alert at<input name="lowStockAt" type="number" min="0" value="5"></label><button class="primary-btn" style="grid-column:1/-1">Save product</button></form>`);$('#productForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{await api('/api/products',{method:'POST',body:JSON.stringify(o)});closeModal();toast('Product added');renderInventory()}catch(err){toast(err.message,true)}}}
window.deleteProduct=async id=>{if(!confirm('Delete this product?'))return;try{await api('/api/products/'+encodeURIComponent(id),{method:'DELETE'});toast('Product deleted');await renderInventory()}catch(err){toast(err.message||'Could not delete product',true)}}
async function renderReports(){const r=await api('/api/reports');const cats=Object.entries(r.byCategory).sort((a,b)=>b[1]-a[1]);$('#page').innerHTML=layoutHead('ANALYTICS','Profit & loss','A simple picture of how your business is performing.')+`<div class="stats"><div class="stat"><small>TOTAL INCOME</small><b>${money(r.income)}</b></div><div class="stat"><small>TOTAL EXPENSES</small><b>${money(r.expenses)}</b></div><div class="stat"><small>NET PROFIT</small><b>${money(r.profit)}</b></div><div class="stat"><small>RECORDS</small><b>${r.transactionCount}</b></div></div><div class="dash-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">EXPENSE BREAKDOWN</span><h3>Where money goes</h3></div></div>${cats.length?cats.map(([name,val])=>`<div class="metric-row" style="margin:16px 0"><div><i class="metric-dot red"></i><span>${esc(name)}</span></div><b>${money(val)}</b></div>`).join(''):'<div class="empty">Add expenses to see your breakdown.</div>'}</section><section class="panel"><div class="panel-head"><div><span class="eyebrow">MARGIN</span><h3>Profit margin</h3></div></div><div style="font:800 42px Manrope;margin:30px 0">${r.income?((r.profit/r.income)*100).toFixed(1):'0.0'}%</div><p style="font-size:11px;color:#7e899a">Net profit as a percentage of paid income.</p></section></div>`}

async function renderSettings(){
 const d=await api('/api/settings'),s=d.settings||{},bp=s.businessProfile||{},ip=s.invoicePreferences||{},tf=s.taxFinance||{},iv=s.inventoryPreferences||{};
 $('#page').innerHTML=layoutHead('WORKSPACE PREFERENCES','Settings','Manage your business details and defaults. Changes are saved to your Savro account.')+
 `<form id="savroSettingsForm" class="settings-stack">
 <section class="panel"><div class="panel-head"><div><span class="eyebrow">BUSINESS PROFILE</span><h3>Business details</h3><p>Used to identify your business in Savro.</p></div></div><div class="form-grid">
 <label>Business name<input name="businessName" required maxlength="100" value="${esc(bp.businessName??d.profile.businessName)}"></label><label>Owner name<input name="ownerName" maxlength="100" value="${esc(bp.ownerName??d.profile.name)}"></label><label>Phone<input name="phone" maxlength="40" value="${esc(bp.phone??d.profile.phone)}"></label><label>Business email<input value="${esc(d.profile.email)}" disabled></label><label>Business address<textarea name="address" maxlength="1000">${esc(bp.address||'')}</textarea></label><label>GSTIN (optional)<input name="gstin" maxlength="30" value="${esc(bp.gstin||'')}"></label><div class="logo-upload-field"><label for="businessLogoFile">Business logo (optional)</label><input id="businessLogoFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><input name="logoUrl" type="hidden" value="${esc(bp.logoUrl||'')}"><div class="logo-upload-preview" id="businessLogoPreview">${bp.logoUrl?`<img src="${esc(bp.logoUrl)}" alt="Business logo preview">`:`<span>No logo selected</span>`}</div><button class="secondary-btn" type="button" id="removeBusinessLogo">Remove logo</button><small>Choose an image up to 500 KB. It will appear in the account avatar.</small></div></div></section>
 <section class="panel"><div class="panel-head"><div><span class="eyebrow">INVOICE PREFERENCES</span><h3>Invoice defaults</h3><p>These are preferences; existing invoices are not changed.</p></div></div><div class="form-grid"><label>Invoice prefix<input name="invoicePrefix" maxlength="12" value="${esc(ip.prefix||'INV-')}"></label><label>Payment terms (days)<input name="paymentTermsDays" type="number" min="0" max="365" value="${Number(ip.paymentTermsDays??14)}"></label><label>Default invoice note<textarea name="invoiceNote" maxlength="1000">${esc(ip.note||'')}</textarea></label><label>Default tax rate (%)<input name="defaultTaxRate" type="number" min="0" max="100" step="0.01" value="${Number(tf.defaultTaxRate??0)}"></label></div></section>
 <section class="panel"><div class="panel-head"><div><span class="eyebrow">TAX & FINANCE</span><h3>Financial preferences</h3></div></div><div class="form-grid"><label>Currency<select name="currency"><option value="INR" ${(tf.currency||'INR')==='INR'?'selected':''}>INR — Indian Rupee (₹)</option></select></label><label>Financial year starts<select name="financialYearStart"><option value="4" ${String(tf.financialYearStart??4)==='4'?'selected':''}>April</option><option value="1" ${String(tf.financialYearStart??4)==='1'?'selected':''}>January</option></select></label><label>Default tax mode<select name="taxMode"><option value="exclusive" ${(tf.taxMode||'exclusive')==='exclusive'?'selected':''}>Tax added to price</option><option value="inclusive" ${tf.taxMode==='inclusive'?'selected':''}>Tax included in price</option></select></label></div></section>
 <section class="panel"><div class="panel-head"><div><span class="eyebrow">INVENTORY</span><h3>Stock preferences</h3><p>Used as a default for newly created items.</p></div></div><div class="form-grid"><label>Default low-stock threshold<input name="lowStockAt" type="number" min="0" step="1" value="${Number(iv.lowStockAt??5)}"></label><label class="settings-check"><input name="lowStockAlerts" type="checkbox" ${iv.lowStockAlerts===false?'':'checked'}> Enable low-stock reminders in Savro</label></div></section>
 <section class="panel"><div class="panel-head"><div><span class="eyebrow">ACCOUNT & SECURITY</span><h3>Change password</h3><p>Use at least 8 characters. Your current password is required.</p></div></div><div class="form-grid"><label>Current password<input name="currentPassword" type="password" autocomplete="current-password"></label><label>New password<input name="newPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password"></label></div><p class="settings-hint">Leave both password fields blank if you do not want to change your password.</p></section>
 <div class="settings-actions"><button class="primary-btn" type="submit">Save settings</button><button class="secondary-btn" type="button" onclick="exportSavroData()">Print / Save data as PDF</button></div></form>`;
 const logoInput=$('#businessLogoFile'),logoValue=$('#savroSettingsForm [name=logoUrl]'),logoPreview=$('#businessLogoPreview');logoInput.onchange=()=>{const file=logoInput.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){toast('Choose a PNG, JPG, WebP or GIF image.',true);logoInput.value='';return}if(file.size>500*1024){toast('Logo must be 500 KB or smaller.',true);logoInput.value='';return}const reader=new FileReader();reader.onload=()=>{logoValue.value=String(reader.result||'');logoPreview.innerHTML=`<img src="${logoValue.value}" alt="Business logo preview">`};reader.readAsDataURL(file)};$('#removeBusinessLogo').onclick=()=>{logoInput.value='';logoValue.value='';logoPreview.innerHTML='<span>No logo selected</span>'};
 $('#savroSettingsForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),currentPassword=String(fd.get('currentPassword')||''),newPassword=String(fd.get('newPassword')||'');try{if(Boolean(currentPassword)!==Boolean(newPassword))throw new Error('Enter both current and new passwords to change your password.');const payload={businessProfile:{businessName:fd.get('businessName'),ownerName:fd.get('ownerName'),phone:fd.get('phone'),address:fd.get('address'),gstin:fd.get('gstin'),logoUrl:fd.get('logoUrl')},invoicePreferences:{prefix:fd.get('invoicePrefix'),paymentTermsDays:Number(fd.get('paymentTermsDays')),note:fd.get('invoiceNote')},taxFinance:{currency:fd.get('currency'),financialYearStart:Number(fd.get('financialYearStart')),defaultTaxRate:Number(fd.get('defaultTaxRate')),taxMode:fd.get('taxMode')},inventoryPreferences:{lowStockAt:Number(fd.get('lowStockAt')),lowStockAlerts:fd.get('lowStockAlerts')==='on'}};await api('/api/settings',{method:'PUT',body:JSON.stringify(payload)});if(currentPassword||newPassword){if(!currentPassword||!newPassword)throw new Error('Enter both current and new passwords to change your password.');await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword,newPassword})});f.currentPassword.value='';f.newPassword.value=''}const me=await api('/api/auth/me');state.user=me.user;$('#businessName').textContent=state.user.businessName||'My Business';setAvatarLogo(fd.get('logoUrl')||'');toast('Settings saved successfully')}catch(err){toast(err.message||'Could not save settings',true)}};
}
async function renderAccounting(){const [r,tx,invoices]=await Promise.all([api('/api/reports'),api('/api/transactions'),api('/api/invoices')]);const outstanding=invoices.filter(i=>!['paid','cancelled'].includes(String(i.status||'').toLowerCase())).reduce((n,i)=>n+Number(i.total||0),0);const income=Number(r.income)||0,expenses=Number(r.expenses)||0;const pendingTx=tx.filter(t=>String(t.paymentStatus||'').toLowerCase()==='pending');$('#page').innerHTML=layoutHead('FINANCIAL WORKSPACE','Accounting','A practical overview based on your existing transactions and invoices.')+`<div class="stats"><div class="stat"><small>RECORDED INCOME</small><b>${money(income)}</b><span class="up">Paid income transactions</span></div><div class="stat"><small>RECORDED EXPENSES</small><b>${money(expenses)}</b><span class="up">Paid expense transactions</span></div><div class="stat"><small>NET RESULT</small><b>${money(income-expenses)}</b><span class="up">Income less expenses</span></div><div class="stat"><small>INVOICE BALANCE</small><b>${money(outstanding)}</b><span class="up">Invoices not marked paid/cancelled</span></div></div><div class="dash-grid accounting-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">ACCOUNT ACTIVITY</span><h3>Recent transactions</h3><p>Existing transaction records; no duplicate entries are created.</p></div><button class="secondary-btn" onclick="state.page='transactions';$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page==='transactions'));render()">View transactions</button></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Type</th><th>Status</th><th>Amount</th></tr></thead><tbody>${tx.slice(0,12).map(t=>`<tr><td>${esc(t.date?new Date(t.date).toLocaleDateString('en-IN'):'—')}</td><td>${esc(t.description)}</td><td>${esc(t.type||'—')}</td><td>${esc(t.paymentStatus||'paid')}</td><td>${money(t.amount)}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No transactions recorded yet.</div></td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">BOOKKEEPING NOTES</span><h3>What these figures mean</h3></div></div><div class="metric-row"><div><i class="metric-dot green"></i><span>All recorded income</span></div><b>${money(income)}</b></div><div class="metric-row" style="margin-top:15px"><div><i class="metric-dot red"></i><span>All recorded expenses</span></div><b>${money(expenses)}</b></div><p class="settings-hint" style="margin-top:20px">This is a management summary, not a complete double-entry ledger or tax filing. Invoice balances are calculated from invoice statuses and may not equal reconciled receivables until payment allocation is implemented.</p><button class="secondary-btn" style="margin-top:10px" onclick="exportSavroData()">Print / Save data as PDF</button></section></div>`}
async function exportSavroData(){
 const printWindow=window.open('','_blank');
 if(!printWindow){toast('Please allow pop-ups for Savro to print your data.',true);return}
 printWindow.document.write('<!doctype html><title>Preparing Savro report…</title><p style="font:16px Arial;padding:24px">Preparing your printable report…</p>');
 try{
  const [settings,transactions,invoices,products,movements]=await Promise.all([api('/api/settings'),api('/api/transactions'),api('/api/invoices'),api('/api/products'),api('/api/stock-movements')]);
  const escHtml=v=>String(v===null||v===undefined?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmtDate=v=>{if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?escHtml(v):d.toLocaleDateString('en-IN')};
  const fmtMoney=v=>'₹'+(Number(v)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
  const table=(headers,rows,empty)=>`<table><thead><tr>${headers.map(h=>`<th>${escHtml(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(x=>`<td>${escHtml(x)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${escHtml(empty||'No records')}</td></tr>`}</tbody></table>`;
  const bp=settings?.businessProfile||{},ip=settings?.invoicePreferences||{},tf=settings?.taxFinance||{},inv=Array.isArray(invoices)?invoices:[],tx=Array.isArray(transactions)?transactions:[],prod=Array.isArray(products)?products:[],mov=Array.isArray(movements)?movements:[];
  const sections=`<section><h2>Business profile & preferences</h2>${table(['Setting','Value'],[['Business name',bp.businessName||'—'],['Owner',bp.ownerName||'—'],['Phone',bp.phone||'—'],['Address',bp.address||'—'],['GSTIN',bp.gstin||'—'],['Invoice prefix',ip.prefix||'—'],['Payment terms (days)',ip.paymentTermsDays??'—'],['Invoice note',ip.note||'—'],['Currency',tf.currency||'INR'],['Financial year starts (month)',tf.financialYearStart??'—'],['Default tax rate (%)',tf.defaultTaxRate??'—'],['Tax mode',tf.taxMode||'—']])}</section>
  <section><h2>Transactions (${tx.length})</h2>${table(['Date','Description','Type','Category','Customer / party','Status','Amount'],tx.map(t=>[fmtDate(t.date),t.description||'—',t.type||'—',t.category||'—',t.partyName||'—',t.paymentStatus||'paid',fmtMoney(t.amount)]),'No transactions recorded.')}</section>
  <section><h2>Invoices (${inv.length})</h2>${table(['Invoice #','Date','Customer','Status','Total'],inv.map(i=>[i.invoiceNumber||i.number||i._id||'—',fmtDate(i.date||i.createdAt),i.customer?.name||i.customerName||'—',i.status||'—',fmtMoney(i.total)]),'No invoices recorded.')}</section>
  <section><h2>Items & inventory (${prod.length})</h2>${table(['Item','SKU','Category','Stock','Purchase price','Selling price','Low-stock alert'],prod.map(p=>[p.name||'—',p.sku||'—',p.category||'—',p.stock??0,fmtMoney(p.buyPrice),fmtMoney(p.sellPrice),p.lowStockAt??'—']),'No items recorded.')}</section>
  <section><h2>Stock movements (${mov.length})</h2>${table(['Date','Item','Movement','Quantity','Reason'],mov.map(m=>[fmtDate(m.date||m.createdAt),m.productName||m.name||m.product?.name||m.productId||'—',m.type||'—',m.quantity??'—',m.reason||'—']),'No stock movements recorded.')}</section>`;
  const html=`<!doctype html><html><head><meta charset="utf-8"><title>Savro Business Data Export</title><style>body{font:12px Arial,sans-serif;color:#172033;margin:24px}h1{font-size:24px;margin-bottom:4px}h2{font-size:16px;margin:24px 0 8px;page-break-after:avoid}p{color:#5b6474}.meta{font-size:11px;color:#687386;margin-bottom:20px}table{width:100%;border-collapse:collapse;margin:8px 0 18px;table-layout:fixed;overflow-wrap:anywhere}th,td{border:1px solid #d9dee7;padding:6px;text-align:left;vertical-align:top}th{background:#f0f3f8}section{page-break-inside:auto}tr{page-break-inside:avoid}@media print{body{margin:12mm}button{display:none}h2{page-break-after:avoid}}.printbar{margin:16px 0;padding:10px 14px;border:0;border-radius:6px;background:#111827;color:white;cursor:pointer}</style></head><body><h1>${escHtml(bp.businessName||'Savro')} — Business Data Export</h1><div class="meta">Generated ${escHtml(new Date().toLocaleString('en-IN'))}. Keep this report private; it may contain customer and financial information.</div><button class="printbar" onclick="window.print()">Print / Save as PDF</button>${sections}<script>window.onload=()=>setTimeout(()=>window.print(),400)<\/script></body></html>`;
  printWindow.document.open();printWindow.document.write(html);printWindow.document.close();toast('Printable report prepared. Choose a printer or “Save as PDF”.');
 }catch(e){printWindow.close();toast(e.message||'Could not prepare printable report',true)}
}

async function renderSubscriptions(){const plans=await api('/api/plans');const active=state.user.subscriptionPlan;const status=state.user.subscriptionStatus;const pending=status==='pending_payment';$('#page').innerHTML=layoutHead('BILLING','Plans that scale with you','Review your plan and subscription status.')+`${status==='trial'&&!state.user.trialExpired?`<div class="notice">✨ You're on a free trial with ${state.user.trialDaysRemaining} day(s) remaining. No payment method is required during your trial.</div>`:''}${state.user.trialExpired?`<div class="notice bad">Your free trial has ended. Your records remain available in read-only mode. Choose a paid plan to resume editing.</div>`:''}${pending?`<div class="notice bad">You've selected ${esc(active||'a paid plan')}. Your payment is awaiting confirmation. Your workspace remains read-only until the subscription is activated.</div>`:''}<div class="plans">${plans.map((p,i)=>`<article class="plan-card ${i===1?'featured':''}">${i===1?'<span class="tag">MOST POPULAR</span>':''}<span class="eyebrow">MONTHLY</span><h3>${esc(p.name)}</h3><div class="price">${money(p.price)}<span>/ month</span></div><ul>${(p.features||[]).map(f=>`<li>${esc(f)}</li>`).join('')}</ul><button class="${active===p.name?'secondary-btn':'primary-btn'}" type="button" onclick="requestPaidPlan('${p._id}')">${active===p.name?(pending?'Selected · payment pending':status==='active'?'Current plan':'Choose '+esc(p.name)):'Choose '+esc(p.name)}</button></article>`).join('')}</div><div class="panel" style="margin-top:15px"><div class="panel-head"><div><span class="eyebrow">YOUR BILLING</span><h3>${esc(active||(status==='trial'?'30-day free trial':'No active paid plan'))}</h3></div><span class="badge ${status==='active'?'green':'amber'}">${esc(status)}</span></div><p style="font-size:11px;color:#7f899a">Paid access starts after the payment provider confirms your subscription.</p></div>`}
window.requestPaidPlan=async id=>{try{if(!window.Razorpay)throw new Error('Secure checkout could not load. Refresh the page and try again.');const plans=await api('/api/plans');const chosen=plans.find(p=>p._id===id);if(!chosen)throw new Error('Plan is no longer available.');if(!state.user||state.user.role==='admin')throw new Error('Customer accounts are required to subscribe.');await api('/api/subscriptions/select',{method:'POST',body:JSON.stringify({planId:id})});const checkout=await api('/api/subscriptions/create',{method:'POST',body:JSON.stringify({planId:id})});if(!checkout.subscriptionId||!checkout.keyId)throw new Error('Checkout could not be prepared. Please contact support.');const options={key:checkout.keyId,subscription_id:checkout.subscriptionId,name:'Savro',description:`${chosen.name} subscription`,prefill:{name:state.user.name||'',email:state.user.email||''},theme:{color:'#0b1220'},handler:async response=>{try{await api('/api/subscriptions/verify',{method:'POST',body:JSON.stringify({razorpay_payment_id:response.razorpay_payment_id,razorpay_subscription_id:response.razorpay_subscription_id,razorpay_signature:response.razorpay_signature})});const me=await api('/api/auth/me');state.user=me.user;showApp();toast('Payment response verified. Subscription activation is being confirmed.')}catch(err){toast(err.message||'Payment verification could not be completed. Contact support before trying again.',true)}}};const rzp=new window.Razorpay(options);rzp.on('payment.failed',response=>{const message=response&&response.error&&response.error.description;toast(message||'Payment failed. No paid access has been activated.',true)});rzp.open()}catch(err){toast(err.message||'Could not start secure checkout',true)}}
async function renderAdmin(){const [users,plans]=await Promise.all([api('/api/admin/users'),api('/api/admin/plans')]);$('#page').innerHTML=layoutHead('CONTROL CENTER','Admin panel','Manage customer access and your subscription catalogue.',`<button class="primary-btn" onclick="openPlan()">+ Add plan</button>`)+`<div class="admin-grid"><section class="panel table-panel"><div class="toolbar"><b>Customers</b><span class="badge gray">${users.length}</span></div><div class="table-wrap"><table><thead><tr><th>Business</th><th>User</th><th>Plan</th><th>Status</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><b>${esc(u.businessName)}</b></td><td>${esc(u.name)}<small>${esc(u.email)}</small></td><td>${esc(u.subscriptionPlan||'Trial')}</td><td><span class="badge ${u.subscriptionStatus==='active'?'green':u.subscriptionStatus==='cancelled'?'red':'amber'}">${esc(u.subscriptionStatus)}</span></td><td><select onchange="adminStatus('${u._id}',this.value)"><option value="trial" ${u.subscriptionStatus==='trial'?'selected':''} disabled>trial · extend below</option><option ${u.subscriptionStatus==='active'?'selected':''}>active</option><option ${u.subscriptionStatus==='past_due'?'selected':''}>past_due</option><option ${u.subscriptionStatus==='cancelled'?'selected':''}>cancelled</option><option ${u.subscriptionStatus==='none'?'selected':''}>none</option><option ${u.subscriptionStatus==='pending_payment'?'selected':''}>pending_payment</option></select>${u.subscriptionStatus==='trial'?`<button class="action-link" onclick="extendTrial('${u._id}')">+30 days</button>`:''}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">PLANS</span><h3>Your pricing</h3></div></div>${plans.map(p=>`<div class="recent"><div><b>${esc(p.name)}</b><small>${money(p.price)} / ${p.period}</small></div><span class="badge ${p.active?'green':'gray'}">${p.active?'Live':'Hidden'}</span></div>`).join('')}</section></div>`}
window.adminStatus=async(id,status)=>{try{await api('/api/admin/users/'+id+'/status',{method:'PATCH',body:JSON.stringify({subscriptionStatus:status})});toast('User status updated')}catch(e){toast(e.message,true)}}
window.extendTrial=async id=>{try{const d=await api('/api/admin/users/'+id+'/extend-trial',{method:'POST',body:JSON.stringify({days:30})});toast(d.message||'Trial extended by 30 days');await renderAdmin()}catch(e){toast(e.message,true)}}
window.openPlan=()=>{openModal(`<h3>Create pricing plan</h3><form id="planForm" class="form-grid"><label>Name<input name="name" placeholder="Business" required></label><label>Price / month<input name="price" type="number" min="1" required></label><label style="grid-column:1/-1">Features<input name="features" placeholder="Unlimited invoices, Inventory, Reports"></label><button class="primary-btn" style="grid-column:1/-1">Create plan</button></form>`);$('#planForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.features=o.features.split(',').map(x=>x.trim()).filter(Boolean);try{await api('/api/admin/plans',{method:'POST',body:JSON.stringify(o)});closeModal();toast('Plan created');renderAdmin()}catch(err){toast(err.message,true)}}}

// Global workspace search: searches the signed-in user's invoices, transactions, and products.
(function setupGlobalSearch(){
  const input = document.getElementById('globalSearch');
  if (!input) return;
  const shell = input.closest('.search');
  if (!shell) return;
  shell.style.position = 'relative';
  const panel = document.createElement('div');
  panel.id = 'globalSearchResults';
  panel.setAttribute('role','listbox');
  panel.style.cssText = 'display:none;position:absolute;top:calc(100% + 9px);right:0;width:min(430px,90vw);max-height:420px;overflow:auto;background:#fff;border:1px solid #e4e7ec;border-radius:14px;box-shadow:0 18px 48px rgba(16,24,40,.18);z-index:1000;padding:7px;color:#101828';
  shell.appendChild(panel);
  let timer = null, requestNo = 0;
  const norm = v => String(v ?? '').toLocaleLowerCase().trim();
  const close = () => { panel.style.display='none'; };
  const destination = {invoice:'sales',transaction:'transactions',product:'inventory'};
  function renderResults(items, query){
    if (!items.length) {
      panel.innerHTML = `<div style="padding:15px 12px;color:#667085;font-size:12px">No matching records found for “${esc(query)}”.</div>`;
      panel.style.display='block'; return;
    }
    panel.innerHTML = `<div style="padding:8px 10px 6px;color:#667085;font-size:10px;font-weight:800;letter-spacing:.08em">SEARCH RESULTS · ${items.length}</div>` + items.map((it,i)=>`<button type="button" data-result-index="${i}" style="display:flex;width:100%;gap:10px;align-items:center;text-align:left;padding:10px;border:0;border-radius:9px;background:transparent;cursor:pointer;color:#101828"><span style="width:34px;height:34px;flex:none;display:grid;place-items:center;background:#f2f4f7;border-radius:10px;font-size:15px">${it.type==='invoice'?'▤':it.type==='transaction'?'↕':'▦'}</span><span style="min-width:0;flex:1"><b style="display:block;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(it.title)}</b><small style="display:block;margin-top:3px;color:#667085;font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(it.subtitle)}</small></span><span style="font-size:9px;color:#667085;background:#f2f4f7;border-radius:20px;padding:4px 7px">${it.type==='invoice'?'Invoice':it.type==='transaction'?'Transaction':'Inventory'}</span></button>`).join('');
    panel.querySelectorAll('[data-result-index]').forEach(btn=>{
      btn.addEventListener('mouseenter',()=>btn.style.background='#f8fafc');
      btn.addEventListener('mouseleave',()=>btn.style.background='transparent');
      btn.addEventListener('click',async()=>{
        const item=items[Number(btn.dataset.resultIndex)];
        input.value=''; close();
        state.page=destination[item.type];
        $$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page));
        await render();
        const rows=Array.from(document.querySelectorAll('#page tbody tr'));
        const needle=norm(item.title);
        const row=rows.find(r=>norm(r.innerText||r.textContent).includes(needle));
        if(row){row.style.outline='2px solid #8b7cf6';row.style.outlineOffset='-2px';row.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>{row.style.outline='';row.style.outlineOffset=''},2600)}
      });
    });
    panel.style.display='block';
  }
  async function search(query, id){
    if(id!==requestNo)return;
    if(query.length<2){close();return;}
    panel.innerHTML='<div style="padding:14px 12px;color:#667085;font-size:12px">Searching invoices, transactions and inventory…</div>';
    panel.style.display='block';
    try{
      const [invoices,transactions,products]=await Promise.all([
        api('/api/invoices'), api('/api/transactions'), api('/api/products')
      ]);
      if(id!==requestNo)return;
      const results=[];
      (Array.isArray(invoices)?invoices:[]).forEach(i=>{
        const title=String(i.number||'Invoice');
        const customer=String(i.customer?.name||'');
        const text=norm([title,customer,i.customer?.phone,i.customer?.email,i.status,i.total].join(' '));
        if(text.includes(query))results.push({type:'invoice',title,subtitle:`${customer||'Customer not specified'} · ${String(i.status||'unpaid')} · ${money(i.total)}`});
      });
      (Array.isArray(transactions)?transactions:[]).forEach(t=>{
        const title=String(t.description||'Transaction');
        const party=String(t.partyName||'');
        const text=norm([title,party,t.category,t.type,t.paymentStatus,t.amount,t.date].join(' '));
        if(text.includes(query))results.push({type:'transaction',title,subtitle:`${party?party+' · ':''}${t.type==='income'?'Income':'Expense'} · ${money(t.amount)} · ${t.paymentStatus||'recorded'}`});
      });
      (Array.isArray(products)?products:[]).forEach(p=>{
        const title=String(p.name||'Product');
        const text=norm([title,p.sku,p.category,p.stock,p.buyPrice,p.sellPrice].join(' '));
        if(text.includes(query))results.push({type:'product',title,subtitle:`${p.sku?`SKU ${p.sku} · `:''}${p.category||'Uncategorized'} · ${Number(p.stock)||0} in stock`});
      });
      renderResults(results.slice(0,20),query);
    }catch(err){
      if(id!==requestNo)return;
      panel.innerHTML=`<div style="padding:14px 12px;color:#b42318;font-size:12px">Search couldn't load records. ${esc(err.message||'Please try again.')}</div>`;
      panel.style.display='block';
    }
  }
  input.addEventListener('input',()=>{
    clearTimeout(timer); const query=norm(input.value); const id=++requestNo;
    if(query.length<2){close();return;}
    timer=setTimeout(()=>search(query,id),250);
  });
  input.addEventListener('focus',()=>{if(norm(input.value).length>=2 && panel.innerHTML)panel.style.display='block'});
  input.addEventListener('keydown',event=>{if(event.key==='Escape'){input.value='';requestNo++;close();input.blur()}else if(event.key==='Enter'){const first=panel.querySelector('[data-result-index="0"]');if(first){event.preventDefault();first.click()}}});
  document.addEventListener('click',event=>{if(!shell.contains(event.target))close()});
})();
loadSignupPlans();
boot();
